syntax = "proto3";
package payments.v1;

service PaymentService {
  rpc CreatePayment(CreatePaymentRequest) returns (PaymentReply);
  rpc GetPayment(GetPaymentRequest) returns (PaymentReply);
  rpc ListPayments(ListPaymentsRequest) returns (ListPaymentsReply);
  rpc CapturePayment(CapturePaymentRequest) returns (PaymentReply);
}

message PaymentReply {
  string payment_id = 1;
  int64 amount_minor = 2;
  string currency = 3;
  string status = 4;
  string account_id = 5;
}

class PaymentGrpcService(payment_service_pb2_grpc.PaymentServiceServicer):
    async def GetPayment(self, request, context):
        payment = self._svc.get_payment(request.payment_id)
        return to_proto(payment)

    async def CapturePayment(self, request, context):
        payment = self._svc.capture_payment(request.payment_id)
        return to_proto(payment)

# app/grpc/converters.py
from decimal import Decimal, ROUND_HALF_UP

def to_minor_units(amount: Decimal) -> int:
    return int((amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)) * 100)

def to_proto(payment: Payment) -> payment_service_pb2.PaymentReply:
    return payment_service_pb2.PaymentReply(
        payment_id=payment.payment_id,
        amount_minor=to_minor_units(payment.amount),
        currency=payment.currency,
        status=payment.status,
        account_id=payment.account_id,
    )

